SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, s.dischtime, s.deathtime, s.los, i.icd_code, i.icd_version, percent_rank() OVER (ORDER BY s.los) AS percentile_rank FROM patients p JOIN admissions s ON p.subject_id = s.subject_id JOIN diagnoses_icd i ON s.subject_id = i.subject_id AND s.hadm_id = i.hadm_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 83 AND 93 AND s.dischtime IS NOT NULL AND s.deathtime IS NULL ORDER BY s.los NULLS LAST;